<template>
  <div>
    <h1>Login</h1>

    <div class="createForm">
      <el-form :model="form">
        <el-form-item label="User Name">
          <el-input v-model="form.username" />
        </el-form-item>

        <el-form-item label="Password">
          <el-input v-model="form.password" />
        </el-form-item>

        <el-form-item>
          <el-button class="submit" type="success" round @click="login">Login</el-button>
          <el-button class="submit" round @click="this.handle('Username Page')">Don't remember a password?</el-button>

        </el-form-item>
      </el-form>
    </div>

  </div>
</template>

<script>
import axios from "axios";
import {reactive} from "vue";
export default {
  name: "LoginPage",
  data() {
    return {
      form: reactive({
        username: '',
        password: ''
      })
    }
  },
  methods: {
    handle(name) {
      this.$router.push({name: name})
    },
    async login() {
      try {
        await axios.post(this.link, this.form)
        this.getTable()
      } catch (e) {
        console.log(e);
      }
    }
  }
}
</script>

